#include <vector>

class Solution {
public:
    int minCost(std::vector<int>& startPos, std::vector<int>& homePos, std::vector<int>& rowCosts, std::vector<int>& colCosts) {
        int cost = 0;
        int rStep = homePos[0] >= startPos[0] ? 1 : -1;
        int cStep = homePos[1] >= startPos[1] ? 1 : -1;

        int r = startPos[0];
        while (r != homePos[0]) {
            r += rStep;
            cost += rowCosts[r];
        }

        int c = startPos[1];
        while (c != homePos[1]) {
            c += cStep;
            cost += colCosts[c];
        }

        return cost;
    }
};

